import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])
    if n > m:
        n, m = m, n

    oo = 1000000000
    size = 1 << n
    curr = [[oo] * size for _ in range(size)]
    curr[0][0] = 0

    for j in range(m):
        next_arr = [[oo] * size for _ in range(size)]
        limit = 1 if j == m - 1 else size
        for c0 in range(size):
            for c1 in range(size):
                if curr[c0][c1] == oo:
                    continue
                for c2 in range(limit):
                    done = 0
                    for i in range(n):
                        if (1 << i) & c1:
                            continue
                        up = i - 1
                        down = i + 1
                        if up >= 0 and ((1 << up) & c1):
                            done |= (1 << i)
                        if down < n and ((1 << down) & c1):
                            done |= (1 << i)
                        if (1 << i) & c0:
                            done |= (1 << i)
                        if (1 << i) & c2:
                            done |= (1 << i)
                    # count bits in done
                    covered = bin(done).count('1')
                    new_val = curr[c0][c1] + n - covered
                    if new_val < next_arr[c1][c2]:
                        next_arr[c1][c2] = new_val
        curr = next_arr

    res = oo
    for row in curr:
        for val in row:
            if val < res:
                res = val
    print(n * m - res)

if __name__ == "__main__":
    solve()
